    fun classify(name: String?, mimeType: String? = null): String {
        val leaf = (name ?: "").replace('\\', '/').substringAfterLast('/')
        extensions[leaf.substringAfterLast('.', "").lowercase(Locale.ROOT)]?.let { return it }
        val mime = (mimeType ?: "").substringBefore(';').trim().lowercase(Locale.ROOT)
        mimeTypes[mime]?.let { return it }
        if (mime.startsWith("image/")) return "file-image"
        if (mime.startsWith("audio/")) return "file-audio"
        if (mime.startsWith("video/")) return "file-video"
        if (mime.startsWith("font/")) return "file-font"
        if (mime.startsWith("model/")) return "file-3d"
        if (mime.startsWith("text/")) return "file-text"
        return "file"
